// Signed distance to a disk

// List of some other 2D distances: https://www.shadertoy.com/playlist/MXdSRf
//
// and iquilezles.org/articles/distfunctions2d


float curveSDF(vec2 p, vec2 anchor, float angle, float len, float amp, float freq)
{
    float cosA = cos(angle);
    float sinA = sin(angle);
    vec2 localP = p - anchor;
    localP = vec2(
        localP.x * cosA + localP.y * sinA,
        -localP.x * sinA + localP.y * cosA
    );
    float t = clamp(localP.x / len, 0.0, 1.0);
    float amplitude = amp;
    float frequency = freq;
    float waveY = sin(t * frequency) * amplitude;
    return length(vec2(localP.x - t * len, localP.y - waveY));
}

float spine(vec2 p)
{
    float d1 = curveSDF(p, vec2(-0.7,0.3), radians(9.), 0.6,-0.04,3.);
    float d2 = curveSDF(p, vec2(-0.7,0.3), radians(190.), 0.3,-0.05,3.);
    float d3 = curveSDF(p, vec2(-1.23,0.039), radians(44.),0.32, -0.01,1.5);
    return min(d3,min(d1,d2));
}
float tail(vec2 p)
{
    float d1 = curveSDF(p, vec2(-1.23,0.039), radians(270.),0.3, -0.06,2.);
    float d2 = curveSDF(p, vec2(-1.285,-0.263), radians(270.0),0.2, 0.01,2.4);
    float d3 = curveSDF(p, vec2(-1.27,-0.27), radians(270.),0.2, 0.01,2.4);
    float d4 = curveSDF(p, vec2(-1.28,-0.47), radians(270.),0.05, -0.01,4.);
    float d5 = curveSDF(p, vec2(-1.26,-0.47), radians(270.),0.05, 0.01,4.);
    return min(d5, min(d4,min(d3,min(d1, d2))));
}
float bl1(vec2 p)
{
    p.x+=1.33;
    p.y+=0.1;
    float d1 = curveSDF(p, vec2(0.33,-0.08), radians(260.),0.4, 0.12,2.5);
    float d2 = curveSDF(p, vec2(.1,0.039), radians(284.),0.5, -0.1,2.);
    float d3 = curveSDF(p, vec2(.1,-0.35), radians(250.),0.3, 0.1,1.8);
    float d4 = curveSDF(p, vec2(.33,-0.48), radians(270.),0.2, -0.01,4.);
    float d5 = curveSDF(p, vec2(.33,-0.67), radians(-40.),0.1, 0.01,2.);
    float d6 = curveSDF(p, vec2(.42,-0.78), radians(105.),0.05, -0.01,2.);
    float d7 = curveSDF(p, vec2(.1,-0.78), radians(0.),0.32, -0.01,2.);
    float d8 = curveSDF(p, vec2(.08,-0.67), radians(-80.),0.11, -0.01,2.);
    return min(d8,min(d7,min(d6,min(d5, min(d4,min(d3,min(d1, d2)))))));
}
float bl2(vec2 p)
{
    p.x+=1.13;
    p.y+=0.1;
    float d = curveSDF(p, vec2(.33,-0.38), radians(270.),0.3, -0.01,4.);
    d = min(d, curveSDF(p, vec2(.33,-0.67), radians(-40.),0.1, 0.01,2.));
    d = min(d, curveSDF(p, vec2(.42,-0.78), radians(105.),0.05, -0.01,2.));
    d = min(d, curveSDF(p, vec2(.23,-0.78), radians(0.),0.2, -0.01,2.));
    return d;
}
float gut(vec2 p)
{
    float d = curveSDF(p, vec2(-.14,-0.3), radians(195.),0.8, 0.05,4.);
    return d;
}
float fl(vec2 p)
{
    float d = curveSDF(p, vec2(.18,-0.08), radians(270.),.685, -0.04,2.9);
    d = min(d, curveSDF(p, vec2(-.12,-0.16), radians(285.),.61, -0.07,2.));
    d = min(d, curveSDF(p, vec2(.17,-0.77), radians(-40.),0.1, 0.01,2.));
    d = min(d, curveSDF(p, vec2(.25,-0.87), radians(105.),0.05, -0.01,2.));
    d = min(d, curveSDF(p, vec2(-.03,-0.87), radians(0.),0.28, -0.01,2.));
    d = min(d, curveSDF(p, vec2(-.03,-0.87), radians(90.),0.1, -0.01,2.));
    return d;
}
float face(vec2 p)
{
    float d = curveSDF(p, vec2(-0.1,0.39), radians(0.),.41, 0.12,2.1);
    d = min(d, curveSDF(p, vec2(.3,0.5), radians(3.),.15, -0.06,1.5));
    d = min(d, curveSDF(p, vec2(.4,0.46), radians(300.),.2, 0.09,2.));
    d = min(d, curveSDF(p, vec2(.57,0.32), radians(280.),.3, 0.04,1.9));
    return d;
}

float trunk(vec2 p)
{
    float d = curveSDF(p, vec2(0.66,0.03), radians(260.),.31, 0.1,2.1);
    d = min(d, curveSDF(p, vec2(0.69,-0.3), radians(270.),.15, -0.06,1.5));
    d = min(d, curveSDF(p, vec2(.63,-0.45), radians(320.),.15, -0.07,2.));
    d = min(d, curveSDF(p, vec2(.64,-0.63), radians(35.),.06, 0.02,3.));
    d = min(d, curveSDF(p, vec2(.64,-0.63), radians(100.),.15, 0.06,2.));
    d = min(d, curveSDF(p, vec2(.56,-0.49), radians(60.),.15, 0.07,1.5));
    d = min(d, curveSDF(p, vec2(.57,-0.33), radians(110.),.05, -0.07,1.1));
    return d;
}

float ear(vec2 p)
{
    float d = curveSDF(p, vec2(0.09,0.49), radians(250.),.3, -0.1,2.5);
    d = min(d, curveSDF(p, vec2(-0.07,0.22), radians(-30.),.15, -0.09,2.1));
    d = min(d, curveSDF(p, vec2(0.02,0.08), radians(300.),.15, 0.06,1.8));
    d = min(d, curveSDF(p, vec2(0.15,-0.02), radians(-30.),.25, -0.05,3.));
    d = min(d, curveSDF(p, vec2(0.35,-0.15), radians(90.),.4, -0.02,5.1));
    return d;
}
float mouth(vec2 p)
{
    float d = curveSDF(p, vec2(0.37,-0.06), radians(-20.),.12, -0.01,5.1);
    d = min(d, curveSDF(p, vec2(0.47,-0.02), radians(-35.),.15, -0.08,2.1));
    d = min(d, curveSDF(p, vec2(0.54,-0.13), radians(363.),.13, -0.2,1.3));
    d = min(d, curveSDF(p, vec2(0.6,-0.13), radians(360.),.08, -0.2,1.2));
    d = min(d, curveSDF(p, vec2(0.615,-0.16), radians(90.),.05, -0.02,2.1));
    d = min(d, curveSDF(p, vec2(0.595,-0.128), radians(190.),.05, -0.02,2.5));
    return d;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 p = (2.0*fragCoord-iResolution.xy)/iResolution.y;

    float d = spine(p);
    d = min(d, tail(p));
    d = min(d, bl1(p));
    d = min(d, bl2(p));
    d = min(d, gut(p));
    d = min(d, fl(p));
    d = min(d, face(p));
    d = min(d, trunk(p));
    d = min(d, ear(p));
    d = min(d, mouth(p));
    vec3 col = (d>0.0) ? vec3(0.9,0.6,0.3) : vec3(0.65,0.85,1.0);
    col *= 1.0 - exp(-9.0*abs(d));
	col *= 0.8 + 0.2*cos(150.0*d);
	col = mix( col, vec3(1.0), 1.0-smoothstep(0.0,0.01,abs(d)) );

    // Output to screen
    fragColor = vec4(col,1.0);
}
